// Pure-file original T012 A criteria; all actual UI/native evidence is generated by the leased driver.
import assert from 'node:assert/strict';
import {readFile,lstat} from 'node:fs/promises';
import {ROOT,save} from './io.mjs';
const r=JSON.parse(await readFile(ROOT+'/raw.json')),cleanup=JSON.parse(await readFile(ROOT+'/cleanup.json')),checks=[];
const test=(name,fn)=>{try{fn();checks.push({name,pass:true});}catch(error){checks.push({name,pass:false,reason:error.message.split('\n')[0]});}};
const cert=(states,id)=>states.find(record=>record.profile.id===id)?.state.certificates??[];
const tab=value=>value.workspace.tabs.find(tab=>tab.id===r.tabId);
const red=value=>{let channels=/^rgba?\(([^)]+)\)/.exec(value)?.[1].split(/[ ,/]+/).slice(0,3).map(Number);if(!channels){const match=/^color\(srgb\s+([^)]*)\)/.exec(value);if(match)channels=match[1].split(/\s+/).slice(0,3).map(n=>Number(n)*255);}return channels?.length===3&&channels.every(Number.isFinite)&&channels[0]>channels[1]+25&&channels[0]>channels[2]+25;};
test('real-App025-own-data-local-TLS-fixture-no-certificate-bypass',()=>{assert.equal(r.status,'executed-unjudged');assert.equal(r.instances.length,2);assert.notEqual(r.instances[0].pid,r.instances[1].pid);for(const instance of r.instances){assert.equal(instance.actualIdentity.userData,r.userData);assert.equal(instance.actualIdentity.rules,'MAP m12-cert.test 127.0.0.1');assert.deepEqual(instance.actualIdentity.forbidden,[]);assert.equal(instance.actualIdentity.version,'42.11.14');assert.equal(instance.setupReloads,1);assert.equal(instance.initialFocus.status,'focused');assert.equal(instance.initialPreparation.attempts,1);}assert.equal(r.tlsFixture.opensslCode,0);assert.equal(r.tlsFixture.privateKeyMode,0o600);assert(r.requests.every(request=>['127.0.0.1','::ffff:127.0.0.1'].includes(request.remote)));});
test('initial-nonlocal-self-signed-load-blocked-with-visible-risk',()=>{assert(new URL(r.url).hostname==='m12-cert.test');assert(r.firstBlocked.dom.visible&&r.firstBlocked.dom.continue===1);assert.equal(r.firstBlocked.dom.title,'此连接不受信任');assert(/风险|读取|篡改/.test(r.firstBlocked.dom.text));assert(/ERR_CERT/.test(tab(r.firstBlocked).failure.errorName));assert.equal(tab(r.firstBlocked).certificate.host,'m12-cert.test');assert(!r.beforeTrustRequests.some(request=>request.url==='/tls'));});
test('only-trusted-UI-continue-loads-actual-TLS-page',()=>{const clicks=r.actions.filter(action=>action.kind==='trusted-ui-click'&&action.text==='我了解风险，继续访问');assert.equal(clicks.length,1);assert.equal(clicks[0].round,1);assert.equal(r.firstTrusted.document.text,'T012_TLS_OWNED');assert.equal(r.firstTrusted.document.url,r.url);assert(r.requests.some(request=>request.round===1&&request.url==='/tls'&&Date.parse(request.at)>=Date.parse(r.trustClickedAt)-1000));});
test('visible-red-untrusted-certificate-icon-and-profile-host-record',()=>{assert.equal(r.firstTrusted.icon.aria,'证书不受信任');assert(r.firstTrusted.icon.visible&&red(r.firstTrusted.icon.color));assert(cert(r.firstTrusted.siteStates,r.profileId).some(certificate=>certificate.host==='m12-cert.test'));assert.equal(tab(r.firstTrusted).profileId,r.profileId);});
test('normal-restart-preserves-same-profile-host-exception',()=>{for(const instance of r.instances){assert.equal(instance.exit.code,0);assert.equal(instance.exit.signal,null);assert.deepEqual(instance.observedProcess.signals,[]);}assert.equal(tab(r.afterRestart).id,r.tabId);assert.equal(tab(r.afterRestart).profileId,r.profileId);assert.equal(r.afterRestart.document.text,'T012_TLS_OWNED');assert(cert(r.afterRestart.siteStates,r.profileId).some(certificate=>certificate.host==='m12-cert.test'));assert(r.afterRestart.icon.visible&&red(r.afterRestart.icon.color));assert(r.requests.some(request=>request.round===2&&request.url==='/tls'&&Date.parse(request.at)<Date.parse(r.revokeClickedAt)));});
test('trusted-profile-manager-revoke-removes-exception-and-revisit-blocks',()=>{assert(cert(r.profileBeforeRevoke,r.profileId).some(certificate=>certificate.host==='m12-cert.test'));assert(!cert(r.profileAfterRevoke,r.profileId).some(certificate=>certificate.host==='m12-cert.test'));assert(r.actions.some(action=>action.kind==='trusted-ui-click'&&action.round===2&&action.text==='撤销'));assert.equal(tab(r.afterRevoke).profileId,r.profileId);assert.equal(tab(r.afterRevoke).certificate.host,'m12-cert.test');assert(/ERR_CERT/.test(tab(r.afterRevoke).failure.errorName));assert(r.afterRevoke.dom.visible);assert.notEqual(tab(r.afterRevoke).certificate.challengeId,tab(r.firstBlocked).certificate.challengeId);});
test('actual-managed-native-CLI-goto-fails-loading-and-cannot-continue',()=>{const command=r.agentGoto;assert.deepEqual(command.argv,['browser','goto','--url',r.url,'--page',r.tabId]);assert(Number.isInteger(command.actual.code)&&command.actual.code!==0);assert.equal(command.actual.signal,null);assert(!command.actual.timedOut);assert.deepEqual(command.actual.cleanupSignals,[]);assert(command.parsed.error&&typeof command.parsed.error.code==='string');assert(!['AUTH_REQUIRED','SCOPE_DENIED','ENTRY_NOT_ACTIVE','INVALID_INPUT','BROWSER_NO_TAB','BROWSER_TAB_NOT_FOUND','BROWSER_STALE_REF','BROWSER_PAUSED','BROWSER_TAB_CLOSED'].includes(command.parsed.error.code),'Authorization/argument/precondition failure is not certificate load-failure proof');const rows=command.host.filter(host=>host.operation_id===command.parsed.operationId&&host.request_id===command.parsed.requestId);assert.equal(rows.length,1);const host=rows[0];assert.equal(host.run_id,command.runId);assert.equal(host.task_id,r.taskId);assert.equal(host.project_id,r.projectId);assert.equal(host.tool_name,'browser.nav.goto');assert.equal(host.package_hash,'d160b699f23c03712297ec6a2025e8898abacc36a4febf6d6229e8beea2b3fd6');assert(['failed','unknown'].includes(host.state));assert.equal(host.attempt_count,1);assert.equal(host.error_code,command.parsed.error.code);assert.equal(host.effect_state,command.parsed.error.effectState);assert.equal(tab(r.afterAgent).profileId,r.profileId);assert.equal(tab(r.afterAgent).certificate.host,'m12-cert.test');assert(/ERR_CERT/.test(tab(r.afterAgent).failure.errorName));assert(!cert(r.afterAgentSiteStates,r.profileId).some(certificate=>certificate.host==='m12-cert.test'));assert.equal(r.requests.filter(request=>request.url==='/tls').length,r.beforeAgentRequests.filter(request=>request.url==='/tls').length);});
test('normal-exit-owned-TLS-key-removal-and-independent-resource-cleanup',()=>{assert.equal(r.appExit.code,0);assert.equal(r.appExit.signal,null);assert.deepEqual(r.observedProcess.signals,[]);assert.equal(r.cleanupErrors.length,0);assert(r.serverClosed&&r.syntheticTLSPrivateKeyDeleted);assert(cleanup.allClear);});
let keyAbsent=false;try{await lstat(ROOT+'/runtime-001/tls/key.pem');}catch(error){keyAbsent=error.code==='ENOENT';}test('synthetic-TLS-private-key-is-actually-absent',()=>assert(keyAbsent));
const result={case:'M12-T012',layers:['A'],status:checks.every(check=>check.pass)?'passed-pending-Root-original-risk-and-red-icon-visual-review':'failed-or-partial',checks,formalNewPasses:0,boundary:'Original seven criteria only plus ownership/cleanup; no old I substituted for current A, no synthetic Agent R claim. CLI error remains its original numeric nonzero/effect, never forced to 0/2. All fake TLS routing and receiver boundaries explicit.'};await save('result.json',result);console.log(JSON.stringify({case:result.case,status:result.status,passed:checks.filter(check=>check.pass).length,total:checks.length,formalNewPasses:0}));if(checks.some(check=>!check.pass))process.exitCode=1;
